import{_ as e,c as s,o as a,ag as d}from"./chunks/framework.DCv_I274.js";const h=JSON.parse('{"title":"Build the foundations","description":"","frontmatter":{},"headers":[],"relativePath":"foundations/index.md","filePath":"foundations/index.md","lastUpdated":null}'),n={name:"foundations/index.md"};function o(r,t,i,l,p,c){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="build-the-foundations" tabindex="-1">Build the foundations <a class="header-anchor" href="#build-the-foundations" aria-label="Permalink to &quot;Build the foundations&quot;">​</a></h1><p>A fresh Laravel app can already answer HTTP requests. Before building features we add the <strong>base layer</strong> every module relies on. Do the steps <strong>in order</strong>: each builds on the previous one.</p><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>You add</th><th>Check</th></tr></thead><tbody><tr><td>01</td><td><a href="/foundations/01-folder-conventions">Folder conventions</a></td><td>where each kind of file goes</td><td>folders exist</td></tr><tr><td>02</td><td><a href="/foundations/02-route-autoloading">Route auto-loading</a></td><td>one route file per module</td><td><code>/api/v1/health</code> answers</td></tr><tr><td>03</td><td><a href="/foundations/03-responses-and-errors">Responses &amp; errors</a></td><td>one JSON envelope, exceptions → status codes</td><td>404 is JSON</td></tr><tr><td>04</td><td><a href="/foundations/04-make-service">make:service</a></td><td>a generator for service classes</td><td>a service file is created</td></tr><tr><td>05</td><td><a href="/foundations/05-query-traits">Query traits</a></td><td><code>?search</code>, filters, <code>?so=</code> sorting</td><td>tinker query</td></tr><tr><td>06</td><td><a href="/foundations/06-activity-log">Activity log</a></td><td>audit trail + automatic 5xx logging</td><td>a row in <code>activity_log</code></td></tr><tr><td>07</td><td><a href="/foundations/07-roles-and-users">Roles &amp; users</a></td><td>roles, user columns, the first admin</td><td><code>migrate --seed</code></td></tr><tr><td>08</td><td><a href="/foundations/08-jwt-access-tokens">JWT access tokens</a></td><td>RSA keys, JwtService, the <code>api</code> guard</td><td>a token in tinker</td></tr><tr><td>09</td><td><a href="/foundations/09-refresh-sessions">Refresh sessions</a></td><td>login, refresh, logout, logout-all</td><td>the login flow works</td></tr><tr><td>10</td><td><a href="/foundations/10-rbac">Permissions (RBAC)</a></td><td>groups, sub-modules, actions, the user group module</td><td>403 without permission</td></tr><tr><td>11</td><td><a href="/foundations/11-api-docs">API docs</a></td><td>generated docs at <code>/docs/api</code></td><td>the page loads</td></tr><tr><td>12</td><td><a href="/foundations/12-file-uploads">File uploads</a></td><td>private disk, uploads table, signed URLs</td><td>upload a signature</td></tr><tr><td>13</td><td><a href="/foundations/13-cors-and-rate-limits">CORS &amp; rate limits</a></td><td>frontend on another port/domain, throttling</td><td>browser call works</td></tr></tbody></table><p>Afterwards, every feature is built the same way: <a href="/guides/creating-a-module">Creating a module</a>.</p><h2 id="packages-you-will-install" tabindex="-1">Packages you will install <a class="header-anchor" href="#packages-you-will-install" aria-label="Permalink to &quot;Packages you will install&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Step</th><th>Why</th></tr></thead><tbody><tr><td><code>spatie/laravel-activitylog</code></td><td>06</td><td>activity log storage</td></tr><tr><td><code>lcobucci/jwt</code>, <code>lcobucci/clock</code></td><td>08</td><td>create and validate JWTs</td></tr><tr><td><code>dedoc/scramble</code></td><td>11</td><td>API documentation from code</td></tr></tbody></table><h2 id="the-finished-structure" tabindex="-1">The finished structure <a class="header-anchor" href="#the-finished-structure" aria-label="Permalink to &quot;The finished structure&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app/</span></span>
<span class="line"><span>├── Auth/JwtGuard.php</span></span>
<span class="line"><span>├── Console/Commands/{MakeServiceCommand,PurgeRefreshSessions}.php</span></span>
<span class="line"><span>├── Constants/{UserRoles,SubModules,ModuleActions}.php</span></span>
<span class="line"><span>├── Exceptions/{InvalidException,UnauthorizedException}.php, Auth/*</span></span>
<span class="line"><span>├── Helpers/{ActivityLogHelper,FileUploadHelper}.php</span></span>
<span class="line"><span>├── Http/</span></span>
<span class="line"><span>│   ├── Controllers/API/v1/{global,modules}/</span></span>
<span class="line"><span>│   ├── Middleware/{ErrorLog,CheckRole,ModulePermission,TrustedOrigin}Middleware.php</span></span>
<span class="line"><span>│   ├── Requests/</span></span>
<span class="line"><span>│   └── Resources/{GlobalResponseResource.php, v1/modules/&lt;feature&gt;/}</span></span>
<span class="line"><span>├── Models/ (+ Concerns/HasUserGroups.php)</span></span>
<span class="line"><span>├── Providers/{AuthServiceProvider,ScrambleServiceProvider}.php</span></span>
<span class="line"><span>├── Services/{JWT/JwtService.php, v1/global, v1/modules}</span></span>
<span class="line"><span>├── Support/{Auth,Rbac}/</span></span>
<span class="line"><span>└── Traits/{Searchable,Filterable,Sortable}.php</span></span>
<span class="line"><span>routes/api.php (loader) + routes/v1/modules/*.php</span></span>
<span class="line"><span>database/seeders/{Rbac/*, data/rbac.php}</span></span>
<span class="line"><span>stubs/service.stub</span></span>
<span class="line"><span>storage/keys/ (never committed)</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Reference code</p><p>Every file shown in these steps is also in the <strong>reference project</strong> that comes with these docs. When something doesn&#39;t work, compare your file with it.</p></div>`,9)])])}const f=e(n,[["render",o]]);export{h as __pageData,f as default};
